@extends('layouts.app')
@section('title', '在线地图')
@section('content')
<div class="space-y-5"><section class="card border-0 bg-gradient-to-br from-emerald-600 to-cyan-700 p-5 text-white"><h1 class="text-2xl font-bold">服务器在线地图</h1><p class="mt-1 text-emerald-50">Dynmap 原生瓦片地图</p></section><section class="card overflow-hidden"><div class="flex flex-wrap gap-3 border-b p-4"><select id="world" class="rounded border p-2"></select><select id="map" class="rounded border p-2"></select><span id="hint" class="text-sm text-slate-500">加载中…</span></div><div id="canvas" class="min-h-[520px] bg-slate-900 p-2"></div></section></div>
<script>
(async()=>{const data=await fetch('/map/data?_='+Date.now()).then(r=>r.json());const worlds=(data.data?.worlds||[]).filter(w=>w.name!=='faces');const ws=document.querySelector('#world'),ms=document.querySelector('#map'),canvas=document.querySelector('#canvas'),hint=document.querySelector('#hint');ws.innerHTML=worlds.map((w,i)=>`<option value="${i}">${w.title||w.name}</option>`).join('');function esc(v){return encodeURIComponent(v)}async function draw(){const w=worlds[ws.value],m=(w.maps||[])[ms.value]||w.maps?.[0];if(!m)return;hint.textContent='读取瓦片…';const map=m.prefix||m.name;const d=await fetch(`/map/tiles-manifest/${esc(w.name)}/${esc(map)}?_=${Date.now()}`).then(r=>r.json());const t=d.tiles||[];canvas.innerHTML=t.map(f=>`<img class="inline-block w-32 h-32 object-cover align-top" src="/map/tile-file?world=${esc(w.name)}&map=${esc(map)}&path=${esc(f)}">`).join('');hint.textContent=`${w.name} / ${map}：${t.length} 块瓦片`;}function setMaps(){const w=worlds[ws.value];ms.innerHTML=(w.maps||[]).map((m,i)=>`<option value="${i}">${m.title||m.name||m.prefix}</option>`).join('');draw()}ws.onchange=setMaps;ms.onchange=draw;setMaps()})().catch(e=>document.querySelector('#hint').textContent=e.message);
</script>
@endsection